// Restores the large trailer assets that are not committed:
//   public/video/*.mp4  — stock footage (Pexels), downloaded here
//   public/cap/**       — real rig footage, regenerated by ../scripts/capture-trailer.mjs (full + face)
// Usage: node scripts/fetch-assets.mjs
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const VIDEO = {
  aerial_fog: "https://videos.pexels.com/video-files/33646601/14298772_1920_1080_24fps.mp4",
  cyber_city: "https://videos.pexels.com/video-files/28615179/12433509_1920_1080_25fps.mp4",
  cyber_scape: "https://videos.pexels.com/video-files/32822471/13990566_1920_1080_24fps.mp4",
  neon_scape: "https://videos.pexels.com/video-files/34719182/14717093_1920_1080_30fps.mp4",
  taxi_rain: "https://videos.pexels.com/video-files/855432/855432-hd_1840_1034_25fps.mp4",
};

fs.mkdirSync(path.join(root, "public/video"), { recursive: true });
for (const [name, url] of Object.entries(VIDEO)) {
  const out = path.join(root, "public/video", `${name}.mp4`);
  if (fs.existsSync(out)) {
    console.log(`have ${name}`);
    continue;
  }
  const res = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0" } });
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  fs.writeFileSync(out, Buffer.from(await res.arrayBuffer()));
  console.log(`got  ${name}`);
}
if (!fs.existsSync(path.join(root, "public/cap/manifest.json"))) {
  console.log("public/cap is missing: run `node scripts/capture-trailer.mjs full` and `node scripts/capture-trailer.mjs face` from the app folder.");
}
